\" y2=\"26.4\"/>\r\n          <line x1=\"1.6\" y1=\"14\" x2=\"4.4\" y2=\"14\"/>\r\n          <line x1=\"23.6\" y1=\"14\" x2=\"26.4\" y2=\"14\"/>\r\n          <line x1=\"5.3\" y1=\"5.3\" x2=\"7.5\" y2=\"7.5\"/>\r\n          <line x1=\"20.5\" y1=\"20.5\" x2=\"22.7\" y2=\"22.7\"/>\r\n          <line x1=\"22.7\" y1=\"5.3\" x2=\"20.5\" y2=\"7.5\"/>\r\n          <line x1=\"7.5\" y1=\"20.5\" x2=\"5.3\" y2=\"22.7\"/>\r\n        </g>\r\n        <!-- 圣光圆环 -->\r\n        <circle cx=\"14\" cy=\"14\" r=\"9.6\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.45\"/>\r\n        <!-- 圣剑：剑身 -->\r\n        <path d=\"M14 3.8 L15.4 11 L15.4 12.6 L12.6 12.6 L12.6 11 Z\" fill=\"currentColor\"/>\r\n        <!-- 圣剑：护手 -->\r\n        <path d=\"M10 13.4 L18 13.4 L18 14.4 L16.4 15.2 L11.6 15.2 L10 14.4 Z\" fill=\"currentColor\"/>\r\n        <!-- 圣剑：剑柄 -->\r\n        <path d=\"M12.8 15.2 L15.2 15.2 L15.2 17.6 L12.8 17.6 Z\" fill=\"currentColor\"/>\r\n        <!-- 圣剑：剑首（残响星钻） -->\r\n        <path d=\"M14 17.4 L15.4 19.4 L14 21.4 L12.6 19.4 Z\" fill=\"currentColor\"/>\r\n      </svg>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- 展开态：带标签页的统一面板 -->\r\n  <div v-else class=\"hub-panel\">\r\n    <div class=\"hub-panel__header\" data-drag-handle=\"1\">\r\n      <span class=\"hub-panel__orn\">✦</span>\r\n      <span class=\"hub-panel__title\">{{ currentTab.label }}</span>\r\n      <span class=\"hub-panel__orn\">✦</span>\r\n      <button class=\"hub-panel__collapse\" type=\"button\" title=\"收起\" @click=\"requestCollapse\">─</button>\r\n    </div>\r\n\r\n    <div class=\"hub-panel__tabs\">\r\n      <button\r\n        v-for=\"t in tabs\"\r\n        :key=\"t.id\"\r\n        type=\"button\"\r\n        class=\"hub-tab\"\r\n        :class=\"{ 'hub-tab--active': t.id === activeTab }\"\r\n        @click=\"activeTab = t.id\"\r\n      >\r\n        <span class=\"hub-tab__icon\">{{ t.icon }}</span>\r\n        <span class=\"hub-tab__label\">{{ t.label }}</span>\r\n      </button>\r\n    </div>\r\n\r\n    <div class=\"hub-panel__content\" :class=\"{ 'hub-panel__content--flush': activeTab === 'hero' }\">\r\n      <PlotPanel v-if=\"activeTab === 'plot'\" />\r\n      <HeroPanel v-else-if=\"activeTab === 'hero'\" :panel-state=\"heroPanelState\" />\r\n      <SummaryPanel v-else />\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script setup lang=\"ts\">\r\nimport { computed, ref } from 'vue';\r\nimport PlotPanel from '../剧情规划大师/App.vue';\r\nimport SummaryPanel from '../总结助手/App.vue';\r\nimport HeroPanel from '../英灵功能/App.vue';\r\n\r\nconst props = defineProps<{\r\n  panelState: { expanded: boolean; collapsed: boolean };\r\n  requestCollapse: () => void;\r\n}>();\r\n\r\n// 英灵殿面板内嵌时始终保持展开态（只显示羊皮卷面板，不显示它自己的悬浮球）\r\nconst heroPanelState = { expanded: true, collapsed: false };\r\n\r\nconst tabs = [\r\n  { id: 'plot', icon: '📖', label: '剧情规划' },\r\n  { id: 'hero', icon: '✦', label: '英灵殿' },\r\n  { id: 'summary', icon: '📝', label: '总结助手' },\r\n] as const;\r\n\r\ntype TabId = (typeof tabs)[number]['id'];\r\n\r\nconst activeTab = ref<TabId>('plot');\r\n\r\nconst currentTab = computed(() => tabs.find(t => t.id === activeTab.value) || tabs[0]);\r\n</script>\r\n\r\n<style scoped>\r\n/* ============================================================\r\n   统一悬浮球（折叠态）\r\n   ============================================================ */\r\n.hub-ball {\r\n  width: 56px;\r\n  height: 56px;\r\n  position: relative;\r\n  border-radius: 50%;\r\n  background: linear-gradient(135deg, #7c3aed, #a855f7);\r\n  border: 2px solid rgba(255, 217, 122, 0.6);\r\n  box-shadow:\r\n    0 8px 28px rgba(124, 58, 237, 0.55),\r\n    0 0 0 4px rgba(168, 85, 247, 0.18),\r\n    inset 0 1px 0 rgba(255, 255, 255, 0.28);\r\n  display: grid;\r\n  place-items: center;\r\n  cursor: grab;\r\n  touch-action: none;\r\n  transition: transform 180ms cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 180ms ease;\r\n  user-select: none;\r\n  -webkit-user-select: none;\r\n}\r\n.hub-ball:active {\r\n  cursor: grabbing;\r\n  transform: scale(0.92);\r\n}\r\n.hub-ball__glow {\r\n  position: absolute;\r\n  inset: 0;\r\n  border-radius: 50%;\r\n  background: radial-gradient(circle at 30% 25%, rgba(255, 255, 255, 0.25) 0%, transparent 60%);\r\n  pointer-events: none;\r\n}\r\n.hub-ball__core {\r\n  width: 42px;\r\n  height: 42px;\r\n  border-radius: 50%;\r\n  display: grid;\r\n  place-items: center;\r\n  background: rgba(255, 255, 255, 0.14);\r\n  border: 1px solid rgba(255, 255, 255, 0.3);\r\n  pointer-events: none;\r\n}\r\n.hub-ball__icon {\r\n  display: block;\r\n  color: #ffd97a;\r\n  filter: drop-shadow(0 0 4px rgba(255, 217, 122, 0.85)) drop-shadow(0 1px 3px rgba(0, 0, 0, 0.4));\r\n}\r\n\r\n/* ============================================================\r\n   统一面板（展开态）\r\n   ============================================================ */\r\n.hub-panel {\r\n  display: flex;\r\n  flex-direction: column;\r\n  width: 100%;\r\n  height: 100%;\r\n  border-radius: 14px;\r\n  overflow: hidden;\r\n  background: rgba(10, 18, 38, 0.92);\r\n  border: 1px solid rgba(139, 92, 246, 0.35);\r\n  box-shadow:\r\n    0 20px 48px rgba(0, 0, 0, 0.45),\r\n    inset 0 1px 0 rgba(255, 255, 255, 0.06);\r\n  backdrop-filter: blur(28px);\r\n  -webkit-backdrop-filter: blur(28px);\r\n  color: #e9e2ff;\r\n}\r\n.hub-panel__header {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 8px 12px;\r\n  background: rgba(255, 255, 255, 0.05);\r\n  border-bottom: 1px solid rgba(255, 255, 255, 0.08);\r\n  cursor: grab;\r\n  user-select: none;\r\n}\r\n.hub-panel__header:active {\r\n  cursor: grabbing;\r\n}\r\n.hub-panel__orn {\r\n  color: #a78bfa;\r\n  font-size: 12px;\r\n}\r\n.hub-panel__title {\r\n  flex: 1;\r\n  font-weight: 700;\r\n  letter-spacing: 1px;\r\n  color: #e9e2ff;\r\n  font-size: 14px;\r\n  text-align: center;\r\n}\r\n.hub-panel__collapse {\r\n  border: none;\r\n  background: rgba(255, 255, 255, 0.08);\r\n  color: #c4b5fd;\r\n  width: 24px;\r\n  height: 24px;\r\n  border-radius: 6px;\r\n  cursor: pointer;\r\n  font-size: 14px;\r\n  line-height: 1;\r\n}\r\n.hub-panel__collapse:hover {\r\n  background: rgba(255, 255, 255, 0.16);\r\n}\r\n\r\n/* 标签栏 */\r\n.hub-panel__tabs {\r\n  display: flex;\r\n  gap: 6px;\r\n  padding: 8px 10px 6px;\r\n  background: rgba(0, 0, 0, 0.18);\r\n  border-bottom: 1px solid rgba(255, 255, 255, 0.07);\r\n}\r\n.hub-tab {\r\n  flex: 1;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 6px;\r\n  padding: 6px 4px;\r\n  border: none;\r\n  border-radius: 8px;\r\n  background: transparent;\r\n  color: #9d9bb8;\r\n  cursor: pointer;\r\n  font-size: 13px;\r\n  font-weight: 600;\r\n  transition: all 0.18s ease;\r\n}\r\n.hub-tab:hover {\r\n  background: rgba(255, 255, 255, 0.06);\r\n  color: #ddd6fe;\r\n}\r\n.hub-tab--active {\r\n  background: linear-gradient(135deg, rgba(124, 58, 237, 0.45), rgba(168, 85, 247, 0.35));\r\n  color: #fff;\r\n  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.15);\r\n}\r\n.hub-tab__icon {\r\n  font-size: 14px;\r\n}\r\n\r\n/* 内容区 */\r\n.hub-panel__content {\r\n  flex: 1;\r\n  min-height: 0;\r\n  overflow-y: auto;\r\n  overflow-x: hidden;\r\n  padding: 10px;\r\n}\r\n.hub-panel__content--flush {\r\n  padding: 0;\r\n}\r\n.hub-panel__content::-webkit-scrollbar {\r\n  width: 6px;\r\n}\r\n.hub-panel__content::-webkit-scrollbar-thumb {\r\n  background: rgba(167, 139, 250, 0.3);\r\n  border-radius: 3px;\r\n}\r\n</style>\r\n\r\n<!-- 非 scoped 覆盖：修复总结助手等面板在窗口内的横向显示不全 / 上下拖拽布局问题。\r\n     因需覆盖到子组件（总结助手/剧情规划等）内部元素，故用全局样式，不放 scoped。 -->\r\n<style>\r\n  .hub-panel__content {\r\n    overflow-x: auto !important;\r\n  }\r\n  .hub-panel__content > div,\r\n  .hub-panel__content .panel-card,\r\n  .hub-panel__content .field-input,\r\n  .hub-panel__content .menu_button {\r\n    width: 100% !important;\r\n    box-sizing: border-box !important;\r\n    min-width: 0 !important;\r\n  }\r\n  .hub-panel__content .toggle-row,\r\n  .hub-panel__content .auto-row,\r\n  .hub-panel__content .field-head,\r\n  .hub-panel__content .model-select-row {\r\n    flex-wrap: wrap !important;\r\n  }\r\n  .hub-panel__content [class*=\"archive\"],\r\n  .hub-panel__content [class*=\"entry\"] button {\r\n    width: 100% !important;\r\n    box-sizing: border-box !important;\r\n    min-width: 0 !important;\r\n    white-space: normal !important;\r\n  }\r\n</style>\r\n"],"sourceRoot":""}]);
